//! Independent read-only URL Inspection integration. The public endpoint is fixed; no live-index test or indexing submission.
use crate::{integrations::{ApiReport,ApiRequest,ApiRow},Result,Url};
use serde_json::{json,Value};
use std::{collections::{BTreeMap,HashSet},time::Duration};
const ENDPOINT:&str="https://searchconsole.googleapis.com/v1/urlInspection/index:inspect";
pub struct Plan {pub property:String,pub urls:Vec<String>,pub language:String}
fn absolute(raw:&str)->Result<Url>{let url=Url::parse(raw.trim()).map_err(|_|"Inspection URL must be absolute HTTP(S)")?;if !matches!(url.scheme(),"http"|"https")||url.host_str().is_none()||!url.username().is_empty()||url.password().is_some()||url.fragment().is_some(){return Err("Inspection URL must be absolute HTTP(S) without credentials or fragment".into())}Ok(url)}
pub fn plan(property:&str,urls:&[String],language:&str)->Result<Plan>{
 if urls.is_empty()||urls.len()>20{return Err("URL Inspection accepts 1–20 explicit URLs per batch".into())}
 if language.is_empty()||language.len()>35||!language.split('-').all(|part|!part.is_empty()&&part.len()<=8&&part.chars().all(|c|c.is_ascii_alphanumeric())){return Err("Use a BCP-47 language code such as en-US or he".into())}
 let property=property.trim();let (normalized,root,prefix)=if let Some(domain)=property.strip_prefix("sc-domain:"){
  let parsed=absolute(&format!("https://{domain}/"))?;if parsed.port().is_some()||parsed.path()!="/"||parsed.query().is_some()||domain.is_empty()||domain.contains(['/',':','@','?','#']){return Err("Domain property must be sc-domain:hostname".into())}
  let host=parsed.host_str().unwrap().trim_end_matches('.').to_string();(format!("sc-domain:{host}"),Some(host),None)
 }else{let parsed=absolute(property)?;if !parsed.path().ends_with('/')||parsed.query().is_some(){return Err("URL-prefix property must end in / and have no query".into())}(parsed.to_string(),None,Some(parsed))};
 let mut seen=HashSet::new();let mut targets=Vec::new();for raw in urls{let target=absolute(raw)?;let inside=if let Some(root)=&root{let host=target.host_str().unwrap().trim_end_matches('.');host==root||host.ends_with(&format!(".{root}"))}else{let prefix=prefix.as_ref().unwrap();target.origin()==prefix.origin()&&target.path().starts_with(prefix.path())};if !inside{return Err("Every inspection URL must be inside the specified Search Console property".into())}if seen.insert(target.to_string()){targets.push(target.to_string())}}
 Ok(Plan{property:normalized,urls:targets,language:language.to_string()})
}
fn text(value:&Value)->Result<Option<String>>{if value.is_null(){return Ok(None)}let string=value.as_str().ok_or("Inspection field has an unexpected JSON type")?;if string.len()>16384{return Err("Inspection field exceeds 16 KiB".into())}Ok(Some(string.into()))}
pub fn parse_row(response:&Value,url:&str)->Result<ApiRow>{
 if response.get("error").is_some(){return Err("Imported inspection response contains an API error; report preserved".into())}
 let result=response.get("inspectionResult").and_then(Value::as_object).ok_or("Expected official inspectionResult response object")?;
 if result.is_empty(){return Err("Inspection result is empty; no observation available".into())}
 let mut metrics=BTreeMap::new();
 if let Some(value)=text(result.get("inspectionResultLink").unwrap_or(&Value::Null))?{metrics.insert("inspection_result_link".into(),json!(value));}
 if let Some(index)=result.get("indexStatusResult"){let index=index.as_object().ok_or("indexStatusResult must be an object")?;for (source,key) in [("verdict","index_verdict"),("coverageState","coverage_state"),("robotsTxtState","robots_txt_state"),("indexingState","indexing_state"),("lastCrawlTime","last_crawl_time"),("pageFetchState","page_fetch_state"),("googleCanonical","google_canonical"),("userCanonical","user_canonical"),("crawledAs","crawled_as")]{if let Some(value)=text(index.get(source).unwrap_or(&Value::Null))?{metrics.insert(key.into(),json!(value));}}
  for (source,key) in [("sitemap","google_sitemaps"),("referringUrls","google_referring_urls")]{if let Some(values)=index.get(source){let values=values.as_array().ok_or("Inspection URL list must be an array")?;if values.len()>1000{return Err("Inspection URL list exceeds 1,000 entries".into())}let entries=values.iter().map(|value|text(value)?.ok_or_else(||"Inspection URL list contains null".into())).collect::<Result<Vec<_>>>()?;metrics.insert(key.into(),json!(entries.join("\n")));}}
 }
 for (source,key) in [("ampResult","amp_verdict"),("richResultsResult","rich_results_verdict")]{if let Some(value)=result.get(source){if !value.is_object(){return Err("Inspection result section must be an object".into())}if let Some(verdict)=text(&value["verdict"])?{metrics.insert(key.into(),json!(verdict));}}}
 if metrics.is_empty(){return Err("Inspection response has no supported observed fields".into())}
 Ok(ApiRow{url:absolute(url)?.to_string(),metrics})
}
pub fn import(property:&str,urls:&[String],language:&str,response:&Value)->Result<Vec<ApiRow>>{let plan=plan(property,urls,language)?;if plan.urls.len()!=1{return Err("An official response has no inspected URL field: supply exactly one URL when importing it".into())}Ok(vec![parse_row(response,&plan.urls[0])?])}
fn perform(request:&ApiRequest,client:&reqwest::blocking::Client,endpoint:&str)->Result<ApiReport>{
 let plan=plan(&request.property,&request.urls,&request.strategy)?;
 if request.credential.trim().is_empty()||request.credential.len()>16384||request.credential.chars().any(char::is_control){return Err("Supply a valid authorized OAuth access token in the application".into())}
 let mut rows=Vec::new();for url in &plan.urls{let body=json!({"inspectionUrl":url,"siteUrl":plan.property,"languageCode":plan.language});let response=crate::integrations::send(client,endpoint,Some(&body),&request.credential,false)?;rows.push(parse_row(&response,url)?);}
 Ok(ApiReport{service:"inspection".into(),property:plan.property,start:String::new(),end:String::new(),strategy:plan.language,rows,truncated:false,note:"Google-index snapshot, not a live URL test or indexing submission. Missing fields are unknown. Explicit batches are capped at 20 URLs; Google property/account quotas still apply. A failed batch is not saved. Credentials were not stored. AMP/rich-result verdicts are summaries; deprecated mobile-usability results and detailed issues are not imported.".into()})
}
pub fn query(request:&ApiRequest)->Result<ApiReport>{
 // Validate all input before client creation or any network request.
 plan(&request.property,&request.urls,&request.strategy)?;
 let client=reqwest::blocking::Client::builder().timeout(Duration::from_secs(30)).redirect(reqwest::redirect::Policy::none()).build()?;
 perform(request,&client,ENDPOINT)
}
#[cfg(test)]mod tests{
 use super::*;
 #[test]fn property_boundaries_and_unicode(){let p=plan("sc-domain:example.test",&["https://shop.example.test/עברית".into(),"https://shop.example.test/%D7%A2%D7%91%D7%A8%D7%99%D7%AA".into()],"he").unwrap();assert_eq!(p.urls.len(),1);assert!(p.urls[0].contains("%D7"));for target in ["https://badexample.test/","https://example.test.evil/","https://u:p@example.test/","https://example.test/#a"]{assert!(plan("sc-domain:example.test",&[target.into()],"he").is_err())}assert!(plan("https://example.test/folder/",&["https://example.test/folder/a".into()],"en-US").is_ok());for target in ["http://example.test/folder/a","https://example.test/folderish/a","https://example.test:8443/folder/a"]{assert!(plan("https://example.test/folder/",&[target.into()],"he").is_err())}}
 #[test]fn bounded_input_and_import_context(){for property in ["https://e.test/no-slash","sc-domain:e.test:80","sc-domain:e.test/path"]{assert!(plan(property,&["https://e.test/".into()],"he").is_err())}assert!(plan("sc-domain:e.test",&vec!["https://e.test/".into();21],"he").is_err());assert!(plan("sc-domain:e.test",&[],"he").is_err());assert!(plan("sc-domain:e.test",&["https://e.test/".into()],"he\n").is_err());assert!(import("sc-domain:e.test",&["https://e.test/a".into(),"https://e.test/b".into()],"he",&json!({"inspectionResult":{"indexStatusResult":{"verdict":"PASS"}}})).is_err())}
 #[test]fn preserves_unknown_and_typed_index_fields(){let row=parse_row(&json!({"inspectionResult":{"indexStatusResult":{"verdict":"NEUTRAL","coverageState":"לא ידוע","sitemap":["https://e.test/map.xml"]},"richResultsResult":{"verdict":"PASS"}}}),"https://e.test/עברית").unwrap();assert_eq!(row.metrics["coverage_state"],"לא ידוע");assert!(!row.metrics.contains_key("last_crawl_time"));assert!(!row.metrics.contains_key("google_canonical"));assert_eq!(row.metrics["google_sitemaps"],"https://e.test/map.xml");assert_eq!(row.metrics["rich_results_verdict"],"PASS");}
 #[test]fn successful_transport_returns_deduplicated_snapshot(){use std::io::{Read,Write};let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let endpoint=format!("http://{}/inspect",listener.local_addr().unwrap());let worker=std::thread::spawn(move||{let(mut stream,_)=listener.accept().unwrap();stream.set_read_timeout(Some(Duration::from_secs(5))).unwrap();let mut head=Vec::new();let mut b=[0];while !head.ends_with(b"\r\n\r\n"){stream.read_exact(&mut b).unwrap();head.push(b[0]);}let head=String::from_utf8(head).unwrap();let length=head.lines().find_map(|line|line.to_lowercase().strip_prefix("content-length:").map(|v|v.trim().parse::<usize>().unwrap())).unwrap();let mut data=vec![0;length];stream.read_exact(&mut data).unwrap();let data:Value=serde_json::from_slice(&data).unwrap();assert_eq!(data["inspectionUrl"],"https://e.test/%D7%A2%D7%91%D7%A8%D7%99%D7%AA");assert_eq!(data["languageCode"],"he");let body=json!({"inspectionResult":{"indexStatusResult":{"verdict":"PASS","coverageState":"נוסף לאינדקס"}}}).to_string();write!(stream,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).unwrap();});let request=ApiRequest{service:"inspection".into(),property:"https://e.test/".into(),start:String::new(),end:String::new(),strategy:"he".into(),credential:"own-fixture-token".into(),urls:vec!["https://e.test/עברית".into(),"https://e.test/%D7%A2%D7%91%D7%A8%D7%99%D7%AA".into()]};let client=reqwest::blocking::Client::builder().no_proxy().timeout(Duration::from_secs(5)).build().unwrap();let report=perform(&request,&client,&endpoint).unwrap();assert_eq!(report.rows.len(),1);assert_eq!(report.rows[0].metrics["coverage_state"],"נוסף לאינדקס");assert!(report.start.is_empty()&&report.end.is_empty()&&!report.truncated);assert!(!serde_json::to_string(&report).unwrap().contains("own-fixture-token"));worker.join().unwrap();}
 #[test]fn rejects_malformed_or_error_observations(){for response in [json!({}),json!({"error":{"message":"private-error"}}),json!({"inspectionResult":{}}),json!({"inspectionResult":{"indexStatusResult":{"verdict":0}}}),json!({"inspectionResult":{"indexStatusResult":{"sitemap":[null]}}})]{let error=parse_row(&response,"https://e.test/").unwrap_err().to_string();assert!(!error.contains("private-error"));}assert!(parse_row(&json!({"inspectionResult":{"indexStatusResult":{"coverageState":"x".repeat(16385)}}}),"https://e.test/").is_err())}
 #[test]fn actual_post_contract_and_failed_batch(){use std::io::{Read,Write};let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let endpoint=format!("http://{}/inspect",listener.local_addr().unwrap());let worker=std::thread::spawn(move||{for index in 0..2{let(mut stream,_)=listener.accept().unwrap();stream.set_read_timeout(Some(Duration::from_secs(5))).unwrap();let mut headers=Vec::new();let mut b=[0];while !headers.ends_with(b"\r\n\r\n"){stream.read_exact(&mut b).unwrap();headers.push(b[0]);}let headers=String::from_utf8(headers).unwrap();assert!(headers.starts_with("POST /inspect HTTP/1.1"));assert!(headers.to_lowercase().contains("authorization: bearer own-fixture-token"));let length=headers.lines().find_map(|line|line.to_lowercase().strip_prefix("content-length:").map(|v|v.trim().parse::<usize>().unwrap())).unwrap();let mut bytes=vec![0;length];stream.read_exact(&mut bytes).unwrap();let body:Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(body["siteUrl"],"sc-domain:e.test");assert_eq!(body["languageCode"],"he");assert_eq!(body["inspectionUrl"],format!("https://e.test/{index}"));assert!(body.get("credential").is_none());let (status,response)=if index==0{("200 OK",r#"{"inspectionResult":{"indexStatusResult":{"verdict":"PASS"}}}"#)}else{("403 Forbidden","own-fixture-token private response")};write!(stream,"HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{response}",response.len()).unwrap();}});let client=reqwest::blocking::Client::builder().no_proxy().timeout(Duration::from_secs(5)).build().unwrap();let request=ApiRequest{service:"inspection".into(),property:"sc-domain:e.test".into(),start:String::new(),end:String::new(),strategy:"he".into(),credential:"own-fixture-token".into(),urls:vec!["https://e.test/0".into(),"https://e.test/1".into()]};let error=perform(&request,&client,&endpoint).unwrap_err().to_string();assert!(error.contains("403"));assert!(!error.contains("own-fixture-token"));worker.join().unwrap();}
}
